3	module ALU(
4	    input[31:0] A, B,
5	    input[3:0] Control,
6	    output[31:0] res,
7	    output zero, overflow
8	);
9	
10	    parameter ALU_ADD  = 4'b0001;
11	    parameter ALU_SUB  = 4'b0010;
12	    parameter ALU_AND  = 4'b0011;
13	    parameter ALU_OR   = 4'b0100;
14	    parameter ALU_XOR  = 4'b0101;
15	    parameter ALU_SLL  = 4'b0110;
16	    parameter ALU_SRL  = 4'b0111;
17	    parameter ALU_SLT  = 4'b1000;
18	    parameter ALU_SLTU = 4'b1001;
19	    parameter ALU_SRA  = 4'b1010;
20	    parameter ALU_Ap4  = 4'b1011;
21	    parameter ALU_Bout = 4'b1100;
22	
23	    reg [31:0] result;
24	    always @(*) begin
25	        case (Control)
26	            ALU_ADD : result = A + B;
27	            ALU_SUB : result = A - B;
28	            ALU_AND : result = A & B;
29	            ALU_OR  : result = A | B;
30	            ALU_XOR : result = A ^ B;
31	            ALU_SLL : result = A << B[4:0];
32	            ALU_SRL : result = A >> B[4:0];
33	            ALU_SLT : result = ($signed(A) < $signed(B)) ? 32'd1 : 32'd0;
34	            ALU_SLTU: result = (A < B) ? 32'd1 : 32'd0;
35	            ALU_SRA : result = $signed(A) >>> B[4:0];
36	            ALU_Ap4 : result = A + 32'd4;
37	            ALU_Bout: result = B;
38	            default : result = 32'b0;
39	        endcase
40	    end
41	
42	    assign res = result;
43	    assign zero = (res == 32'b0);
44	    assign overflow = (Control == ALU_ADD) ? (A[31] == B[31]) && (res[31] != A[31]) :
45	                      (Control == ALU_SUB) ? (A[31] != B[31]) && (res[31] != A[31]) :
46	                      1'b0;
47	
48	endmodule

`timescale 1ns / 1ps

module ImmGen(
            input  wire [2:0] ImmSel,
            input  wire [31:0] inst_field,
            output[31:0] Imm_out
    );
    parameter Imm_type_I = 3'b001;
    parameter Imm_type_B = 3'b010;
    parameter Imm_type_J = 3'b011;
    parameter Imm_type_S = 3'b100;
    parameter Imm_type_U = 3'b101;

    reg [31:0] imm;
    always @(*) begin
        case (ImmSel)
            Imm_type_I: imm = {{20{inst_field[31]}}, inst_field[31:20]};
            Imm_type_B: imm = {{19{inst_field[31]}}, inst_field[31], inst_field[7],
                               inst_field[30:25], inst_field[11:8], 1'b0};
            Imm_type_J: imm = {{11{inst_field[31]}}, inst_field[31], inst_field[19:12],
                               inst_field[20], inst_field[30:21], 1'b0};
            Imm_type_S: imm = {{20{inst_field[31]}}, inst_field[31:25], inst_field[11:7]};
            Imm_type_U: imm = {inst_field[31:12], 12'b0};
            default   : imm = 32'b0;
        endcase
    end
    assign Imm_out = imm;
endmodule
`timescale 1ns / 1ps

module cmp_32(  input [31:0] a,
                input [31:0] b,
                input [2:0] ctrl,
                output c
    );
    parameter cmp_EQ  = 3'b001;
    parameter cmp_NE  = 3'b010;
    parameter cmp_LT  = 3'b011;
    parameter cmp_LTU = 3'b100;
    parameter cmp_GE  = 3'b101;
    parameter cmp_GEU = 3'b110;

    wire res_EQ  = a == b;
    wire res_NE  = ~res_EQ;
    wire res_LT  = (a[31] & ~b[31]) || (~(a[31] ^ b[31]) && a < b);
    wire res_LTU = a < b;
    wire res_GE  = ~res_LT;
    wire res_GEU = ~res_LTU;

    wire EQ  = ctrl == cmp_EQ ; 
    wire NE  = ctrl == cmp_NE ; 
    wire LT  = ctrl == cmp_LT ; 
    wire LTU = ctrl == cmp_LTU;
    wire GE  = ctrl == cmp_GE ; 
    wire GEU = ctrl == cmp_GEU;

    assign c = EQ  & res_EQ  |
               NE  & res_NE  |
               LT  & res_LT  |
               LTU & res_LTU |
               GE  & res_GE  |
               GEU & res_GEU ;

endmodule`timescale 1ns / 1ps
